# Derive the routing table from the graded grid - never hand-author it.
import json, collections

rows = json.load(open('bench/results/replay-fullgrid.json'))
by_class = collections.defaultdict(list)
for r in rows:
    by_class[(r['class'], r['mode'])].append(r)

table = {}
for (qclass, mode), cells in sorted(by_class.items()):
    if any(c['verdict'] == 'FAIL' for c in cells):
        continue                      # route-only-among-correct: ineligible
    cost = sum(c['tokens_in'] for c in cells) / len(cells)
    if qclass not in table or cost < table[qclass][1]:
        table[qclass] = (mode, cost)

for qclass, (mode, cost) in sorted(table.items()):
    print(f'{qclass:<12} -> {mode:<10} (~{cost:,.0f} tok, 100% correct)')
